"""Create the review board from HyperFrames' nine captured pose images."""
from pathlib import Path
import json
import html

root = Path(__file__).resolve().parent
shots = json.loads((root / "shots.json").read_text())
stills = sorted((root / "boards/stills").glob("frame-*.png"))
assert len(stills) == len(shots) == 9, "Capture all nine poses before building the board"
e = html.escape
frames = []
for i, (shot, still) in enumerate(zip(shots, stills), 1):
    frames.append(f'''<article class="frame" id="shot-{i}">
    <a href="stills/{e(still.name)}" aria-label="Open full-size frame {i}"><img src="stills/{e(still.name)}" alt="Storyboard pose: {e(shot['title'])}" width="1920" height="1080"></a>
    <div class="details"><p class="time">{shot['start']:02}–{shot['end']:02}s · {e(shot['act'])}</p>
    <h2 class="title">{i:02}: {e(shot['title'])}</h2><p class="words">{e(shot['words'])}</p>
    <p><strong>Motion:</strong> {e(shot['action'])}</p><p class="source"><strong>Screen source:</strong> {e(shot['source'])}</p></div></article>''')
page = '''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>TableIQ — launch storyboard v2</title><style>
@font-face{font-family:Instrument;src:url('../assets/fonts/instrument-sans-latin-500-normal.woff2');font-weight:500}
@font-face{font-family:Instrument;src:url('../assets/fonts/instrument-sans-latin-600-normal.woff2');font-weight:600}
*{box-sizing:border-box}html{background:#f1f6fb;color:#0c1a2b;scroll-behavior:smooth}body{margin:0;font:500 16px/1.6 Instrument,system-ui,sans-serif}a{color:#0b7480;text-underline-offset:4px}header,main,footer{max-width:1480px;margin:auto;padding:32px}header{padding-top:64px}.eyebrow{color:#475d76;font-size:14px}h1{font-size:clamp(34px,4vw,58px);line-height:1.08;letter-spacing:-1.7px;max-width:900px;font-weight:600;margin:20px 0}header p{max-width:940px}.intro{font-size:21px;line-height:1.5}.meta{color:#475d76}nav{display:flex;gap:20px;flex-wrap:wrap;margin:30px 0 0}nav a{font-size:15px}main{display:grid;grid-template-columns:1fr 1fr;gap:32px}.frame{background:#fff;border:1px solid #b7cadd;border-radius:8px;overflow:hidden;scroll-margin-top:20px}.frame>a{display:block;line-height:0;background:#f1f6fb}.frame img{width:100%;height:auto}.details{padding:24px}.time{font-size:14px;color:#0b7480;margin:0 0 8px}.title{font-size:23px;line-height:1.25;margin:0 0 16px;font-weight:600;letter-spacing:-.5px}.details p{margin:14px 0}.details .source{color:#475d76;font-size:14px}.note{padding:20px 24px;background:#e4edf6;border-radius:8px;max-width:1050px}.script{max-width:1050px}footer{padding-bottom:64px}button{font:inherit;padding:10px 18px;color:#f1f6fb;background:#0c1a2b;border:0;border-radius:4px;cursor:pointer}:focus-visible{outline:3px solid #0b7480;outline-offset:4px}@media(max-width:850px){header,main,footer{padding:24px}header{padding-top:36px}main{grid-template-columns:1fr;gap:24px}.details{padding:20px}}@media print{nav,button{display:none}header,main,footer{padding:12px}main{display:block}.frame{break-inside:avoid;margin-bottom:24px}.frame img{max-height:300px;object-fit:contain}}
</style></head><body><header><p class="eyebrow">TableIQ · Creative direction v2 · 16 November 2026</p><h1>One investigation.<br>More room to work.</h1><p class="intro">A free, open-source database client first. Optional AI and visible agent activity follow a real task.</p><p class="meta">56 seconds · 1920 × 1080 · Light Pearl editorial scenes · Genuine native app screens</p><div class="note"><strong>Script and storyboard stage.</strong> These are nine posed stills, not a new finished film. Capture pickups and older footage are identified on every frame. No product controls, AI outputs or performance numbers are invented.</div><nav aria-label="Storyboard navigation">NAV</nav></header><main>FRAMES</main><footer><div class="script"><h2>Why this direction</h2><p>The opening is a developer pain the viewer can recognize. The middle shows one useful database investigation. The two returned orders make the result concrete. MCP appears after the database client is understood.</p><p><strong>Theme:</strong> brand Pearl #F1F6FB, Ledger Ink #0C1A2B and Lumen Deep #0B7480. Keep actual captured app colors intact.</p><p><strong>Claim boundary:</strong> TablePlus documents a two-tab free-trial limit. DBeaver is also free and open source. “Built with Rust” is a fact; faster-than claims require matched benchmarks.</p><p><a href="../SCRIPT.md">Full script, exact narration and capture list</a> · <a href="../SPEC.md">Production specification</a> · <a href="stills/contact-sheet.jpg">All nine images</a></p><p><a href="https://www.linkedin.com/posts/ajay-misra_today-were-launching-router-for-wallet-ugcPost-7526705352344588288-t3kl/">Reference inspected</a> · <a href="https://tableplus.com/pricing">TablePlus source</a> · <a href="https://dbeaver.io/about/">DBeaver source</a></p><p>Next production steps: capture the marked interactions, animate from these poses, record narration, add licensed audio, review frames and export.</p><button onclick="window.print()">Print / save as PDF</button></div></footer></body></html>'''
nav = ''.join(f'<a href="#shot-{i}">{i:02} · {e(s["act"])}</a>' for i, s in enumerate(shots, 1))
(root / "boards/storyboard.html").write_text(page.replace('NAV', nav).replace('FRAMES', ''.join(frames)))
print(root / "boards/storyboard.html")
